def maximal_runs(cells,bg,H,W):
    cells=set(cells);used=set();res=[]
    ordered=sorted(cells)
    for p in ordered:
        if p in used:continue
        for d in [(-1,0),(1,0),(0,-1),(0,1)]:
            q=p+d
            if q not in cells or (0<=p[0]<H and 0<=p[1]<W)==False: continue
            s=[p,q];seen={p,q}
            x,y=q
            while True:
                nxt=(x+d[0],y+d[1])
                if not(0<=nxt[0]<H and 0<=nxt[1]<W) or nxt not in cells:break
                s.append(nxt);seen.add(nxt);x,y=nxt
            # check maximality: extend both ends
            ok=True; e0,e1=s[0],s[-1]
            for d2,d3 in [( (-d[0],-d[1]),True), ]:
                pass
            # try extending backward from s[0] along -d
            nx,ny=e0[0]-d[0],e0[1]-d[1]
            extb=False
            while True:
                if not(0<=nx<H and 0<=ny<W) or nx,ny not in cells: break
                extb=True; s.insert(0,(nx,ny)); seen.add((nx,ny)); nx-=d[0]; ny-=d[1]
            nx,ny=e1[0]+d[0],e1[1]+d[1]
            extf=False
            while True:
                if not(0<=nx<H and 0<=ny<W) or nx,ny not in cells: break
                extf=True; s.append((nx,ny)); seen.add((nx,ny)); nx+=d[0]; ny+=d[1]
            if not(extb or extf):
                res.append((len(s),d,tuple(sorted(s))))
                used|=set(s)
    return sorted(res,key=lambda z:-z[0])

